/* PharmTox Exam 4 study guide questions (PHAR 443): mania, serotonin, antidepressants, psychostimulants, pain and opioids. Built from Study_Guide_Exam_4.docx and the Serotonin 2025, Anti-Depressants 2025, Pain and Opiates Part I 2025 and Psychosis and Mania 2025/2026 lecture decks. Topics the Exam 4 question bank (PT4Q) and the older PT4 set already cover well are left out. Psychostimulant items and the opioid drug table come from standard pharmacology because no psychostimulant deck was supplied and the opioid drug table slides are pictures. */
const SG = (t, d, q, a, w, e, s) => Q("PT4S", d, q, a, w, e, t, s);
const MA = "Mania and bipolar disorder", SE = "Serotonin", AD = "Antidepressants", PS = "Psychostimulants", OP = "Pain and opioids";
const sM = (n) => "Psychosis and Mania lecture (2025), slide " + n, sS = (n) => "Serotonin lecture, slide " + n, sA = (n) => "Anti-Depressants lecture, slide " + n, sO = (n) => "Pain and Opiates lecture, slide " + n, sP = (n) => "Psychostimulant lecture (2025), slide " + n, sD = "Study Guide Exam 4, opioid drug table (standard pharmacology)";
// Mania
SG(MA, 1, "How does hypomania differ from mania?", "Hypomania does not cause functional impairment or hospitalization and has no psychotic symptoms", ["Hypomania always lasts longer than mania and requires hospitalization", "Hypomania is a depressive episode with low energy and low mood", "Hypomania requires psychotic symptoms to be diagnosed"], "Both involve elevated or irritable mood with more energy and less need for sleep. Mania causes marked impairment, may need hospitalization and may include psychosis.", sM(44));
SG(MA, 1, "Which of these can induce a manic episode and should be considered before a bipolar diagnosis?", "Dopamine agonists, antidepressants, stimulants, cocaine and amphetamines", ["Only a family history of depression, a recent bereavement or a recent move to a new city", "Beta blockers, ACE inhibitors and thiazide diuretics", "Antibiotics such as amoxicillin and cephalexin"], "Medications and substances can trigger mania. Substance-induced mania alone should not be relied on to diagnose bipolar disorder.", sM(44));
SG(MA, 2, "Which statement about lithium is most accurate?", "No other drug has beaten its prevention of future manic and depressive phases, and it uniquely lowers suicide risk", ["It is the only drug that works in acute mania and has no other options", "It works within minutes of the first dose and needs no level monitoring", "It is mainly metabolized by CYP3A4 in the liver and cleared in bile"], "Lithium is the benchmark mood stabilizer. Valproate, carbamazepine and antipsychotics also treat acute mania.", sM(45));
SG(MA, 3, "Which proposed actions of lithium are described in the lecture?", "Inhibition of inositol phosphate breakdown and of GSK-3 beta, with reduced PKC activity", ["Blockade of dopamine D2 receptors in the striatum and the mesolimbic pathway, as for antipsychotics", "Blockade of the serotonin transporter and the norepinephrine transporter", "Activation of GABA-A receptors by binding the benzodiazepine site"], "Li+ inhibits inositol monophosphatase and GSK-3 beta and lowers PKC activity. Its precise antimanic mechanism is not established.", sM(46));
SG(MA, 2, "When should a serum lithium level be drawn?", "10 to 12 hours after the last oral dose", ["Right after the morning dose, at the peak", "Only when symptoms of toxicity start", "Two hours after the evening meal, regardless of dosing time"], "A standard trough timing makes levels comparable. Lithium has a low therapeutic index, so regular levels are essential.", sM(47));
SG(MA, 2, "Why does lithium carry a high risk of toxicity when a patient becomes dehydrated or starts a thiazide?", "It is cleared by the kidneys, and sodium or volume depletion increases its reabsorption", ["It is metabolized by the liver, and dehydration inhibits the CYP enzymes that clear it from blood", "It is cleared by the lungs, and dehydration thickens airway secretions", "It is stored in fat, and weight loss releases the stored drug into blood"], "Lithium is a monovalent cation handled like sodium by the kidney. Thiazides, NSAIDs, ACE inhibitors and ARBs raise levels.", sM(54));
SG(MA, 2, "Which findings suggest lithium toxicity rather than the usual fine tremor?", "Vomiting, coarse tremor, ataxia and confusion", ["Mild thirst, increased urination and a fine tremor that is present at therapeutic levels", "Dry cough and a rash", "Isolated constipation"], "Fine tremor can occur at therapeutic levels. Coarse tremor, ataxia, dysarthria or confusion mean the drug should be held and the patient assessed urgently.", sM(56));
SG(MA, 2, "A patient taking lithium starts ibuprofen and then develops vomiting, coarse tremor and unsteady walking. What is the best next step?", "Hold lithium and arrange an urgent toxicity evaluation", ["Increase the lithium dose to control the breakthrough mania, then recheck the level later", "Add benztropine for parkinsonism", "Continue treatment until the next routine level"], "NSAIDs reduce renal lithium clearance. The symptoms point to toxicity, so the patient needs a level, renal function and electrolytes without waiting for a routine visit.", sM(54));
SG(MA, 2, "Which monitoring and safety concerns apply to valproate (divalproex) in mania?", "Liver injury, pancreatitis, low platelets and serious fetal harm", ["Agranulocytosis requiring weekly blood counts for the first months and the need for weekly absolute neutrophil counts", "Hypothyroidism and diabetes insipidus", "Stevens-Johnson syndrome tied to HLA-B*1502"], "Monitor liver tests, CBC with platelets and levels when indicated. Divalproex is the form most often used because it causes fewer GI effects.", sM(49));
SG(MA, 3, "Valproate is added to a patient already taking lamotrigine. What is the main concern?", "Valproate raises lamotrigine exposure and the risk of serious rash, so the lamotrigine dose must be lowered", ["Valproate lowers lamotrigine levels, so the lamotrigine dose must be raised", "The two drugs cancel each other's sodium channel effects, so response is lost", "The combination causes lithium-like renal toxicity that needs dialysis"], "Valproate inhibits lamotrigine metabolism. Lamotrigine also needs slow titration to reduce rash risk.", sM(49));
SG(MA, 2, "Which finding before starting carbamazepine is linked to Stevens-Johnson syndrome and toxic epidermal necrolysis?", "HLA-B*1502", ["Low thyroid-stimulating hormone", "CYP2D6 poor metabolizer status", "A positive tyramine challenge"], "Patients with HLA-B*1502 are at higher risk. Carbamazepine also induces its own metabolism, so exposure changes early in treatment.", sM(49));
SG(MA, 2, "Which statement about antipsychotics in acute mania is correct?", "Most atypical antipsychotics are indicated for acute mania, except clozapine, iloperidone, brexpiprazole and lurasidone", ["None of the atypical antipsychotics are indicated for acute mania, only for schizophrenia", "Only first-generation antipsychotics such as haloperidol work in acute mania", "They work only if the patient also has psychotic symptoms during the episode"], "Antipsychotics are often combined with lithium, valproate or carbamazepine even without psychotic features because their actions complement each other.", sM(50));
SG(MA, 2, "Which drug is used to keep bipolar I patients well over time but does not control acute mania?", "Lamotrigine", ["Valproate", "Haloperidol", "Carbamazepine"], "Lamotrigine helps prevent depressive recurrence in maintenance treatment. It is not effective for acute mania and needs slow titration.", sM(48));
// Serotonin
SG(SE, 1, "What is the rate-limiting enzyme in serotonin synthesis?", "Tryptophan hydroxylase", ["Aromatic amino acid decarboxylase", "Monoamine oxidase A", "Tyrosine hydroxylase"], "Tryptophan crosses into the brain on the LAT1 transporter. Tryptophan hydroxylase makes 5-hydroxytryptophan, which AADC converts to serotonin.", sS(5));
SG(SE, 1, "Which transporter loads serotonin into synaptic vesicles?", "VMAT2", ["SERT", "LAT1", "NET"], "VMAT2 packs serotonin into vesicles. SERT removes serotonin from the synapse and ends the signal.", sS(6));
SG(SE, 1, "What ends the signal of synaptically released serotonin?", "Reuptake by the serotonin transporter SERT into neurons", ["Breakdown by acetylcholinesterase in the cleft", "Diffusion into the bloodstream, followed by excretion of unchanged serotonin by the kidney", "Re-uptake by the vesicular transporter VMAT2"], "SERT is Na+ coupled with 12 transmembrane domains. It is the target of SSRIs and SNRIs.", sS(9));
SG(SE, 1, "Which enzyme is the primary route of serotonin metabolism?", "Monoamine oxidase A", ["Catechol-O-methyltransferase", "Tryptophan hydroxylase", "Acetylcholinesterase"], "MAO-A makes 5-HIAA, the main metabolite excreted in urine.", sS(10));
SG(SE, 1, "Which molecule is the major urinary metabolite of serotonin?", "5-HIAA", ["Melatonin", "Tryptophan", "Normetanephrine"], "5-hydroxyindoleacetic acid comes from MAO-A. Serotonin is also a precursor of melatonin.", sS(10));
SG(SE, 2, "Which serotonin receptor family couples to Gq and activates the PLC, IP3 and DAG pathway?", "5HT2", ["5HT1", "5HT4", "5HT6"], "5HT2 receptors couple to Gq/G11. 5HT1 and 5HT5 couple to Gi/o, and 5HT4, 5HT6 and 5HT7 couple to Gs.", sS(8));
SG(SE, 2, "Which serotonin receptor is a ligand-gated ion channel?", "5HT3", ["5HT1A", "5HT2A", "5HT7"], "5HT3 is the only monoamine neurotransmitter receptor that is a ligand-gated ion channel. All the others are G protein coupled.", sS(8));
SG(SE, 2, "Which serotonin receptors couple to Gs and raise cAMP?", "5HT4, 5HT6 and 5HT7", ["5HT1A, 5HT1B and 5HT1D", "5HT2A, 5HT2B and 5HT2C", "5HT3 and 5HT5"], "Gs coupling activates adenylyl cyclase. 5HT1 and 5HT5 inhibit it through Gi/o.", sS(8));
SG(SE, 2, "Which receptors act as autoreceptors that reduce serotonin release or firing?", "5HT1A (on cell bodies) and 5HT1B/1D (on terminals)", ["5HT3 receptors on cell bodies and 5HT4 receptors on terminals", "5HT2A receptors in the cortex and 5HT2C receptors in the choroid plexus", "5HT6 receptors in the striatum and 5HT7 receptors in the gut"], "These Gi/o coupled autoreceptors provide negative feedback. SSRIs initially activate them until they desensitize.", sS(8));
SG(SE, 2, "Where is the serotonin transporter expressed besides the raphe nuclei?", "Platelets, placenta, lung, gut and adrenal gland", ["Only the cerebellum, where it is found at high density", "Only red blood cells, skeletal muscle and the kidney tubules", "Only the retina, the lens and the inner ear hair cells"], "SERT is found in the raphe nucleus and many peripheral tissues, which explains peripheral effects of SSRIs.", sS(9));
SG(SE, 1, "Which cells in the gut make and store most of the body's serotonin?", "Enterochromaffin cells", ["Paneth cells", "Goblet cells", "Parietal cells"], "Enterochromaffin cells of the gastric and intestinal mucosa are the main site of serotonin synthesis and storage.", sS(11));
SG(SE, 1, "How do platelets handle serotonin?", "They take it up from the blood, store it in granules and release it when damaged", ["They synthesize it from tryptophan using tryptophan hydroxylase inside their granules, then release it", "They break it down to 5-HIAA locally using monoamine oxidase A", "They store it only after converting it to melatonin and release it at night"], "Platelets cannot make serotonin. They take it up through SERT and release it at sites of injury.", sS(11));
SG(SE, 2, "Which receptor mainly mediates serotonin-induced vasoconstriction of vascular smooth muscle?", "5HT2", ["5HT1 on endothelium", "5HT3", "5HT4"], "Constriction is mainly 5HT2 on smooth muscle. Dilation can come from 5HT1 receptors on endothelium that release relaxing factors.", sS(13));
SG(SE, 2, "Which factors decide the net effect of serotonin on a blood vessel?", "Endothelial integrity, smooth muscle activation, sympathetic tone and local conditions", ["Only the serotonin concentration in the blood, with nothing depending on the condition of the vessel wall", "Only the patient's age and sex, since receptors are the same everywhere", "Only whether the vessel is an artery or a vein, regardless of tone"], "Serotonin has both constrictor and dilator properties. 5HT2 antagonists block constriction and unmask dilation.", sS(13));
SG(SE, 2, "Which area of physiology is influenced by serotonin?", "Sleep, appetite, temperature regulation, nociception and mood", ["Only muscle contraction at the neuromuscular junction and nothing in the brain", "Only bile secretion and gallbladder emptying in the liver", "Only bone remodeling and calcium handling in the kidney"], "Serotonin affects many functions including sleep, cognition, sensory perception, motor activity, appetite, sexual behavior and hormone secretion.", sS(15));
SG(SE, 2, "Lorcaserin was approved for weight loss. What is its mechanism?", "5HT2C receptor agonist", ["5HT2C receptor antagonist", "Serotonin releaser that also blocks reuptake", "5HT1A partial agonist"], "5HT2C activation reduces appetite. Fenfluramine and dexfenfluramine promote serotonin release and block reuptake.", sS(16));
SG(SE, 2, "Which finding links serotonin to aggression and impulsivity?", "Low CSF 5-HIAA correlates with violent impulsivity", ["High platelet serotonin predicts calm behavior", "Excess 5HT3 receptor activity in the gut, which causes aggression through the vagus nerve", "Raised urinary melatonin predicts impulsivity"], "Mice lacking 5HT1B are extremely aggressive, and an MAO-A gene mutation was tied to extreme aggressiveness.", sS(16));
SG(SE, 2, "Which statement about migraine is consistent with the lecture?", "The trigeminal nerve is sensitive to changes in serotonin, and serotonin levels vary across the phases of an attack", ["Migraine is caused only by low blood sugar, and serotonin plays no role in attacks", "Serotonin levels are constant through every phase, and the trigeminal nerve is insensitive to it", "Urinary serotonin metabolites fall during most attacks, which proves serotonin loss causes migraine"], "Urinary serotonin metabolites rise during most attacks. Drugs that release stored serotonin, such as reserpine and fenfluramine, can precipitate migraine.", sS(21));
SG(SE, 2, "How do triptans help stop a migraine?", "They activate 5HT1B/1D receptors to constrict dilated intracranial vessels, block trigeminal firing and calm inflammation", ["They block 5HT3 receptors to stop nausea only, with no effect on the headache itself", "They inhibit MAO-A in the trigeminal ganglion and raise serotonin there", "They release serotonin from platelets, which dilates the intracranial vessels"], "Triptans are indole derivatives. They also reduce nausea and vomiting. The relative importance of vascular and neural effects is not settled.", sS(22));
SG(SE, 1, "Sumatriptan is used for which purpose?", "Acute treatment of migraine", ["Prevention of migraine", "Weight loss", "Treatment of major depression"], "Sumatriptan is given by autoinjector, nasal spray or oral dose to stop an attack. It is not used for prevention.", sS(23));
SG(SE, 2, "Which drug is an ergot derivative used to prevent migraine and other vascular headaches?", "Methysergide", ["Sumatriptan", "Rizatriptan", "Buspirone"], "Ergots are partial agonists or antagonists at 5HT, dopamine and adrenergic receptors. Methysergide is used for prophylaxis, while ergots for an attack should be given as soon as the headache starts.", sS(25));
SG(SE, 2, "What are ergot alkaloids?", "Fungal products that act as partial agonists or antagonists at serotonin, dopamine and adrenergic receptors", ["Synthetic indole drugs that only block 5HT3 receptors and are used for nausea", "Selective 5HT1B/1D agonists with no activity at any other receptor", "Plant alkaloids from the opium poppy that inhibit MAO-A and MAO-B"], "LSD is an ergot derivative that interacts with most 5HT receptors. Their acute antimigraine effect likely comes from 5HT1B/1D.", sS(24));
SG(SE, 2, "What combination can trigger serotonin syndrome?", "An SSRI combined with a triptan, an MAOI or a norepinephrine reuptake inhibitor", ["A triptan combined with acetaminophen and caffeine for a headache that lasts several hours", "An SSRI combined with a thiazide diuretic, because both lower sodium", "Lithium combined with a high water intake and a low salt diet"], "It often occurs when an antidepressant is started or increased, or when serotonergic drugs are combined.", sS(27));
SG(SE, 2, "Which signs fit serotonin syndrome?", "Restlessness, confusion, shivering, tachycardia, diarrhea, muscle twitching and rigidity, and fever", ["Bradycardia, constipation and a slow onset over weeks, with no fever", "Miosis, slow breathing and sedation only, with normal temperature, normal reflexes and a normal heart rate", "An isolated fine tremor with normal temperature, heart rate and mental status"], "The triad is cognitive, autonomic and neuromuscular (hyperreflexia, clonus). Treatment is stopping the serotonergic drugs, supportive care and sometimes cyproheptadine.", sS(27));
// Antidepressants
SG(AD, 1, "What defines persistent depressive disorder (dysthymia)?", "Sad or dark mood most of the day, on most days, for two years or more", ["Alternating manic and depressive episodes that each last at least one week", "A single depressive episode lasting two weeks after a major life loss", "Depressive episodes that occur only in winter months and remit each spring"], "Major depression is unipolar. Bipolar I and II disorders are manic-depressive illness.", sA(5));
SG(AD, 1, "Which disease type is also called unipolar depression?", "Major depression", ["Bipolar I disorder", "Persistent depressive disorder", "Cyclothymia"], "Major depression is more common in women. Bipolar I and II involve mania or hypomania.", sA(5));
SG(AD, 2, "Which medical conditions can cause secondary depressive symptoms?", "Hypothyroidism, Parkinson disease and inflammatory conditions", ["Hypertension, mild eczema and seasonal allergies only", "Seasonal allergies and iron deficiency anemia only, which are both common", "Only Cushing disease, with no other medical conditions involved"], "Depression also complicates cancer, diabetes and cardiovascular disease, especially after myocardial infarction.", sA(7));
SG(AD, 2, "Why is there a delay of about 3 to 4 weeks before antidepressants reach full effect?", "Part is pharmacokinetic, and part is delayed postsynaptic and receptor adaptation", ["The drugs only start to bind transporters after the third week of dosing", "Serotonin is not released until week 3, so nothing changes before that", "The liver must first convert every antidepressant into an active drug, which takes about three weeks"], "Sleep improves sooner, while mood and cognition improve later.", sA(15));
SG(AD, 2, "Which are long-term effects of antidepressant treatment?", "Altered receptor density and sensitivity, increased BDNF and increased hippocampal neurogenesis", ["Permanent loss of serotonin transporters in the gut and loss of platelet function across the body", "Destruction of raphe neurons followed by regrowth of the same cells", "Irreversible inhibition of MAO in the liver for every antidepressant class"], "Sustained NE or 5HT signaling increases downstream gene products such as BDNF and influences dendritic spine formation and synaptogenesis.", sA(13));
SG(AD, 2, "For how long is maintenance treatment typically continued after a successful first phase of antidepressant therapy?", "6 to 12 months, then the drug is gradually withdrawn", ["2 weeks, then stopped abruptly", "Exactly 6 days", "Lifelong for every patient"], "A patient chronically depressed for more than 2 years may be advised to take an antidepressant lifelong.", sA(15));
SG(AD, 2, "Which statement about antidepressants and bipolar disorder is correct?", "They should not be monotherapy, and TCAs, SNRIs and less so SSRIs can switch a patient into mania", ["They are first-line monotherapy for bipolar I because they treat both poles", "SSRIs are the antidepressants most likely to cause a switch, more than TCAs", "They cure the manic phase and are the best treatment for acute mania"], "Antidepressants need to be paired with a mood stabilizer in bipolar disorder.", sA(16));
SG(AD, 1, "What does the 14-day rule refer to?", "Wait at least 14 days after stopping an MAOI before starting an SSRI or other serotonergic antidepressant", ["Antidepressants must be taken for 14 days before the first effect is seen", "A 14-day trial at a fixed dose is needed before the dose can be raised", "A 14-day supply is the maximum quantity allowed per prescription"], "MAO is irreversibly inhibited, so it takes up to 2 weeks to synthesize new enzyme. Starting a serotonergic drug sooner risks serotonin syndrome.", sA(32));
SG(AD, 2, "How long after stopping duloxetine is a wait needed before beginning an MAOI?", "5 days", ["No wait is needed", "14 days", "5 weeks"], "Duloxetine needs a 5 day wait before an MAOI, and venlafaxine and duloxetine need 7 to 14 days after an MAOI before starting. Fluoxetine needs 5 weeks because of norfluoxetine.", sA(40));
SG(AD, 2, "Which statement about first-generation versus second-generation antidepressants is correct?", "TCAs and MAOIs are more toxic, while SSRIs and SNRIs are safer and used more often", ["The first generation is safer and is used most often, while the second is reserved for severe cases", "Second-generation drugs act only on dopamine, while first-generation drugs act only on GABA", "TCAs are second generation and SSRIs are first generation, and both are equally toxic"], "Both generations enhance serotonergic or noradrenergic transmission.", sA(9));
SG(AD, 2, "How do TCAs and MAOIs raise monoamine transmission?", "TCAs block SERT and NET, while MAOIs inhibit monoamine metabolism", ["TCAs inhibit MAO and MAOIs block SERT and NET", "Both classes block dopamine receptors", "Both classes directly agonize 5HT1A receptors"], "MAOIs increase the amount of neurotransmitter in storage granules available for release.", sA(10));
SG(AD, 2, "Which classes act at the SERT transporter?", "SSRIs, SNRIs and TCAs", ["MAOIs and SSRIs only", "Bupropion and mirtazapine", "Trazodone and benzodiazepines"], "MAOIs act on the enzyme, not the transporter.", sA(11));
SG(AD, 2, "Repeated SSRI treatment leads to which autoreceptor change?", "Gradual downregulation and desensitization of the 5HT1A and 5HT1D autoreceptors", ["Permanent activation of 5HT1A autoreceptors", "Increased 5HT synthesis through upregulated autoreceptors", "Loss of postsynaptic 5HT3 receptors"], "At first SSRIs stimulate autoreceptors and reduce serotonin release. With repeated treatment these desensitize and serotonergic transmission increases.", sA(25));
SG(AD, 2, "Which receptor effect causes insomnia, anxiety and decreased libido with SSRIs?", "Overactivation of 5HT2 receptors", ["Blockade of H1 receptors", "Activation of 5HT3 receptors", "Blockade of alpha-1 adrenergic receptors in the vasculature"], "5HT3 stimulation causes nausea, diarrhea and vomiting. Most SSRIs are not sedating because they do not block histamine receptors.", sA(31));
SG(AD, 2, "Which two SSRIs are approved for PTSD?", "Sertraline and paroxetine", ["Fluoxetine and citalopram", "Escitalopram and fluvoxamine", "Sertraline and fluoxetine"], "Sertraline has a broad range of uses including GAD, OCD, panic, social anxiety and PMDD.", sA(23));
SG(AD, 2, "Which SSRI has the longest half-life, so withdrawal symptoms are least likely?", "Fluoxetine", ["Paroxetine", "Sertraline", "Fluvoxamine"], "Its active metabolite norfluoxetine has a half-life of 1 to 2 weeks, which allows a once-weekly formulation.", sA(33));
SG(AD, 2, "Why is fluoxetine a concern for a postmenopausal woman taking tamoxifen?", "It inhibits CYP2D6, which activates tamoxifen", ["It induces CYP3A4 and speeds tamoxifen clearance", "It competes for estrogen receptors", "It causes tamoxifen to deposit in fat"], "Paroxetine and fluoxetine are potent CYP2D6 inhibitors. Venlafaxine and desvenlafaxine are weak inhibitors and are not contraindicated.", sA(30));
SG(AD, 3, "Which SSRI directly inhibits CYP1A2, CYP2C19 and CYP3A4?", "Fluvoxamine", ["Paroxetine", "Sertraline", "Escitalopram"], "Paroxetine and fluoxetine are mainly potent CYP2D6 inhibitors.", sA(32));
SG(AD, 2, "Citalopram and escitalopram need careful dosing in elderly patients because:", "CYP2C19 metabolism decreases with age", ["They are cleared entirely by the kidney", "They inhibit CYP2D6 strongly", "They raise lithium levels"], "CYP2D6 is involved in the metabolism of most SSRIs, but these two depend on CYP2C19.", sA(30));
SG(AD, 2, "Which SSRI is described as the most sedating and known for weight gain and sexual side effects?", "Paroxetine", ["Sertraline", "Fluoxetine", "Escitalopram"], "Paroxetine also has a short half-life and no active metabolites, so discontinuation symptoms are strong. It is linked to birth defects in the first trimester.", sA(29));
SG(AD, 2, "SSRI doses are adjusted based on:", "Clinical response and side effects, since blood levels do not closely correlate with effect", ["Serum drug levels, like lithium, with a target range for every patient", "Plasma norepinephrine concentration measured at each visit, before any change in dose is made", "The CYP2D6 phenotype of every patient, tested before the first dose"], "Do not confuse this with TCAs, which have a narrow window and benefit from plasma monitoring.", sA(31));
SG(AD, 1, "Which antidepressants are SNRIs?", "Venlafaxine, desvenlafaxine, duloxetine, milnacipran and levomilnacipran", ["Sertraline, paroxetine, citalopram, escitalopram and fluoxetine", "Mirtazapine, trazodone, nefazodone, vortioxetine and bupropion", "Phenelzine, isocarboxazid, tranylcypromine, selegiline, moclobemide and rasagiline"], "SNRIs block both SERT and NET without a tricyclic structure.", sA(34));
SG(AD, 2, "Which adverse effect is notable for immediate-release venlafaxine at higher doses?", "Sustained diastolic hypertension", ["Priapism", "Agranulocytosis", "Liver failure"], "The risk is reduced with the extended-release form.", sA(39));
SG(AD, 2, "Venlafaxine mainly affects which transporter at low doses and which more at higher doses?", "SERT at low doses, with NET inhibition added at higher doses", ["NET at low doses and SERT only at very high doses, with no activity at lower doses", "DAT at low doses and SERT at high doses", "Both equally at every dose"], "This dose-dependent profile explains why higher doses also affect blood pressure.", sA(41));
SG(AD, 2, "Desvenlafaxine is:", "The active demethylated metabolite of venlafaxine", ["A prodrug of duloxetine", "An MAOI used as a patch", "A tricyclic antidepressant with strong antimuscarinic effects and a narrow window"], "It has a more predictable pharmacokinetic profile and may raise blood pressure less than venlafaxine.", sA(42));
SG(AD, 2, "Duloxetine is distinct among antidepressants because it is also used for:", "Fibromyalgia, diabetic peripheral neuropathy and chronic musculoskeletal pain", ["Bulimia nervosa, smoking cessation and prevention of seasonal depressive episodes in winter", "Parkinson disease motor symptoms and restless legs syndrome", "Acute migraine, acute pain crises and opioid withdrawal symptoms"], "It should be avoided in severe liver disease and uncontrolled narrow-angle glaucoma.", sA(43));
SG(AD, 2, "Which receptors does trazodone block?", "5HT2 and alpha-1 adrenergic receptors", ["5HT3 and H1 receptors", "D2 and 5HT2A receptors", "Muscarinic acetylcholine and NMDA glutamate receptors in the cortex"], "Low doses are widely used for insomnia. Priapism is a rare adverse effect.", sA(49));
SG(AD, 2, "Which antidepressant was withdrawn in several countries after rare cases of liver failure?", "Nefazodone", ["Trazodone", "Bupropion", "Mirtazapine"], "Nefazodone blocks 5HT2 receptors and weakly inhibits serotonin uptake.", sA(51));
SG(AD, 2, "Which antidepressant is sedating, blocks H1, alpha-2 and 5HT2A/2C/3 receptors, and often causes weight gain?", "Mirtazapine", ["Bupropion", "Sertraline", "Venlafaxine"], "It is a good choice for depressed patients with insomnia. Agranulocytosis is a rare risk.", sA(52));
SG(AD, 2, "Which receptor profile belongs to vortioxetine?", "Partial agonist at 5HT1A and 5HT1B, and antagonist at 5HT1D, 5HT3 and 5HT7", ["Antagonist at 5HT2 and alpha-1 receptors with weak SERT inhibition", "Agonist at NMDA receptors with fast antidepressant effects that begin within hours of a dose", "Inhibitor of NET and DAT only, with no action on serotonin receptors"], "It also inhibits SERT. This receptor mix is unlike the SSRIs.", sA(48));
SG(AD, 2, "Bupropion increases which neurotransmitters, and by what main mechanism?", "Norepinephrine and dopamine, by inhibiting NET and DAT", ["Serotonin and norepinephrine, by inhibiting SERT and NET", "Serotonin, by blocking 5HT2 receptors", "GABA, by inhibiting GABA transaminase"], "It may also release NE and DA. The hydroxybupropion metabolite contributes to the effect.", sA(55));
SG(AD, 2, "Bupropion should be avoided in patients with:", "Seizure disorders or bulimia", ["Insomnia", "Hypothyroidism", "Obesity"], "Seizure risk is dose and concentration dependent. It is approved for depression, seasonal depression and smoking cessation.", sA(59));
SG(AD, 2, "Which atypical antipsychotic is used with fluoxetine for treatment-resistant depression?", "Olanzapine", ["Aripiprazole", "Quetiapine", "Clozapine"], "Aripiprazole (D2 partial agonist) and quetiapine are also used adjunctively with SSRIs or SNRIs.", sA(61));
SG(AD, 2, "What is the mechanism of ketamine as an antidepressant?", "NMDA receptor antagonism that increases AMPA signaling and BDNF release", ["Inhibition of MAO-A and MAO-B, which raises monoamines within hours", "Blockade of the serotonin transporter, with a clinical delay of several weeks before effect", "Agonism at 5HT1A receptors on raphe neurons, as with buspirone"], "Effects begin within hours, which is useful in treatment-resistant depression and acute suicidal ideation. Esketamine (Spravato) is the NMDA antagonist version.", sA(62));
SG(AD, 2, "Which pair of drugs matches their targets: brexanolone and esketamine?", "Brexanolone modulates GABA-A for postpartum depression, and esketamine antagonizes NMDA receptors", ["Brexanolone blocks NMDA receptors, and esketamine modulates GABA-A receptors", "Both drugs block SERT and are used for first-line major depression", "Both drugs are MAO inhibitors given as a daily transdermal patch"], "Both are newer options beyond monoamine drugs.", "Anti-Depressants lecture, slides 18 and 19");
SG(AD, 2, "Which receptors do TCAs block that cause sedation, dry mouth and orthostatic hypotension?", "H1, muscarinic and alpha-1 receptors", ["D2, 5HT3 and NMDA receptors in the striatum and the limbic system", "GABA-A and opioid receptors", "Beta-1 and 5HT4 receptors"], "H1 block causes sedation, muscarinic block causes blurred vision, dry mouth, constipation and urinary retention, and alpha-1 block causes orthostatic hypotension.", sA(68));
SG(AD, 2, "Why do TCAs need plasma monitoring?", "They have a narrow therapeutic window, and about 7 percent of patients are slow CYP2D6 metabolizers", ["They are given only by injection, so levels are checked before each dose", "They have no active metabolites and are cleared unchanged by the kidneys", "Their effect correlates with urine pH and with the patient's diet"], "A CYP2D6 variant can cause a 30-fold difference in plasma concentration at the same dose. CYP2D6 inhibitors such as bupropion and SSRIs raise TCA levels.", sA(67));
SG(AD, 2, "Why are tertiary amine TCAs such as doxepin and amitriptyline used at low doses?", "To treat insomnia and pain conditions", ["To treat psychosis alone, since TCAs are the first-line drugs for schizophrenia", "To cause weight loss", "To act as anticoagulants"], "TCAs are not first line for depression because of side effects, but are useful for pain because of NE and 5HT roles in nociception.", sA(65));
SG(AD, 2, "Which MAOIs are approved in the U.S. for depression and irreversibly inhibit both MAO-A and MAO-B?", "Tranylcypromine, phenelzine and isocarboxazid", ["Moclobemide, rasagiline, safinamide and linezolid, which are MAO inhibitors used for other purposes", "Sertraline and venlafaxine", "Maprotiline and amoxapine"], "They block metabolism of endogenous monoamines and also of dietary tyramine.", sA(71));
SG(AD, 3, "Why does an MAOI plus a tyramine-rich food risk a hypertensive crisis?", "Inhibited MAO-A lets tyramine reach the circulation, enter adrenergic terminals and release catecholamines", ["Tyramine blocks alpha receptors and causes severe vasodilation and low blood pressure", "Tyramine inhibits the norepinephrine transporter and directly lowers sympathetic tone", "Tyramine induces CYP2D6 and speeds clearance of the MAOI, which causes withdrawal"], "MAO-A in the gut wall and MAO-A and B in the liver normally degrade dietary tyramine.", sA(75));
SG(AD, 2, "How does transdermal selegiline lower the risk of a tyramine reaction?", "At low doses it selectively inhibits MAO-B and spares MAO-A in the gut", ["It permanently inactivates tyramine", "It is metabolized by the liver only", "It blocks alpha receptors"], "Higher doses also inhibit MAO-A. The patch is used for depression.", sA(73));
SG(AD, 2, "Which drug interactions are especially serious with MAOIs?", "SSRIs or tryptophan, meperidine, tramadol and sympathomimetics such as pseudoephedrine", ["Calcium supplements and antacids, which block MAOI absorption in the gut and so lower the dose", "Acetaminophen and ibuprofen, which raise MAOI levels in the liver", "Penicillin and cephalosporins, which compete for renal secretion"], "The most serious interaction is serotonin syndrome. Cold, allergy and diet products with sympathomimetics should be avoided.", sA(76));
SG(AD, 2, "Besides hypertensive crisis, which life-threatening toxicity occurs with chronic MAOI use?", "Hepatotoxicity", ["Pulmonary fibrosis", "Pancreatitis", "Aplastic anemia"], "Many patients are slow acetylators, which raises plasma levels.", sA(75));
SG(AD, 2, "Maprotiline and amoxapine are:", "Tetracyclic antidepressants", ["MAO inhibitors", "SSRIs", "NMDA antagonists"], "Maprotiline increases norepinephrine (Ludiomil). Amoxapine (Asendin) has multiple neurotransmitter effects.", "Anti-Depressants lecture, slides 18 and 19");
// Psychostimulants
SG(PS, 1, "Which neurotransmitter systems are modulated to treat ADHD?", "Dopamine and norepinephrine", ["GABA and glycine", "Acetylcholine and histamine", "Serotonin and melatonin only"], "Stimulants raise dopamine and norepinephrine in prefrontal and striatal circuits that control attention and executive function.", sP(7));
SG(PS, 2, "Which description fits methylphenidate?", "It blocks the dopamine and norepinephrine transporters and is a Schedule II drug", ["It reverses the serotonin transporter and is a Schedule IV drug", "It inhibits MAO-B and is not a controlled substance in the United States, so it needs no scheduling", "It blocks D2 receptors and is a Schedule III drug used for sedation"], "Amphetamines also release dopamine and norepinephrine from terminals. Methylphenidate is first line for ADHD with a smoother onset and offset.", sP(13));
SG(PS, 2, "Which drug class has Schedule IV status and is used for narcolepsy and shift work sleep disorder?", "Modafinil and armodafinil", ["Amphetamine salts", "Methylphenidate", "Atomoxetine"], "These wake-promoting agents have lower abuse potential than amphetamines.", sP(16));
SG(PS, 2, "Which stimulant is not a controlled substance and acts as a selective norepinephrine reuptake inhibitor?", "Atomoxetine", ["Dextroamphetamine", "Methylphenidate", "Lisdexamfetamine"], "The lecture lists it as not a classic stimulant, used as an ADHD alternative. Bupropion is the other non-stimulant adjunct.", sP(9));
SG(PS, 2, "Which clinical pearl applies to amphetamine and methylphenidate?", "They can raise heart rate and blood pressure and reduce appetite", ["They commonly cause hypotension, a slow heart rate and weight gain with long-term use", "They are safe to combine with MAOIs", "They are first-line for acute mania"], "Cardiovascular monitoring, appetite and sleep effects matter. Mixed amphetamine salts need a 14-day washout from MAOIs.", sP(14));
SG(PS, 1, "Which subtypes of ADHD are described?", "Predominantly inattentive, predominantly hyperactive-impulsive and combined", ["Early onset, late onset and adult only", "Mild, moderate and severe", "Cognitive, motor and sleep related"], "Inattentive symptoms include poor focus and forgetfulness. Hyperactive-impulsive symptoms include fidgeting and interrupting.", sP(3));
SG(PS, 2, "What happens in the prefrontal cortex and anterior cingulate cortex of a patient with ADHD during attention tasks?", "They show hypoactivity, which stimulants help normalize", ["They show hyperactivity that stimulants suppress", "They are structurally absent", "They are unchanged, and stimulants act only in the cerebellum"], "fMRI studies show improved connectivity between the PFC and the striatum (executive control) and between the PFC and the parietal cortex (selective attention).", sP(6));
SG(PS, 2, "What does the Goldilocks zone describe for dopamine and norepinephrine in the prefrontal cortex?", "Too little causes distractibility and impulsivity, and too much causes anxiety and rigidity", ["More dopamine always improves attention", "Too little causes anxiety and too much causes sedation", "Norepinephrine alone sets the optimum, and dopamine has no role"], "Psychostimulants try to bring neurotransmission into the optimal range.", sP(7));
SG(PS, 2, "Which prefrontal cortex functions are regulated by dopamine and norepinephrine?", "Working memory, impulse control, focus and goal-directed behavior", ["Heart rate and breathing", "Pain transmission and reflexes", "Hunger and thirst only"], "Impaired signaling here produces the inattention and impulsivity of ADHD.", sP(7));
SG(PS, 2, "Which statement correctly defines a psychostimulant?", "A drug that raises CNS activity, alertness and attention mainly through dopamine and norepinephrine", ["A drug that lowers CNS activity through GABA", "A drug that blocks opioid receptors", "A drug that acts only on serotonin"], "The groups are amphetamines, methylphenidate compounds and modafinil-like agents, plus non-stimulant adjuncts.", sP(9));
SG(PS, 2, "How do amphetamines and methylphenidate differ in mechanism?", "Amphetamines promote vesicular release and reverse transporters, while methylphenidate blocks DAT and NET reuptake", ["Amphetamines block reuptake only, and methylphenidate causes release", "Both act only by blocking MAO", "Both work only on serotonin receptors"], "The comparison table lists amphetamines as release, methylphenidate as reuptake inhibition and modafinil as enhancing wake-promoting transmitters.", sP(19));
SG(PS, 2, "Which comparison of abuse potential and schedule is correct?", "Amphetamines high and C-II, methylphenidate moderate and C-II, modafinil low and C-IV", ["Amphetamines low and C-IV, methylphenidate high and C-II, modafinil moderate and C-II", "All three are C-II with high abuse potential", "Amphetamines moderate and C-III, methylphenidate low and C-IV, modafinil high and C-II"], "Modafinil and armodafinil have low abuse risk and less sympathetic activation.", sP(19));
SG(PS, 2, "How can a methylphenidate patch (Daytrana) limit insomnia?", "Remove it after about 9 hours", ["Apply it only at bedtime", "Apply it to broken skin", "Replace it every 3 days"], "The patch is useful for pediatric adherence. Monitoring includes blood pressure, heart rate, appetite, weight, sleep and growth in children.", sP(13));
SG(PS, 2, "Why is lisdexamfetamine considered to have a smoother profile and lower abuse potential?", "It is an inactive prodrug converted to dextroamphetamine in red blood cells", ["It is converted to dextroamphetamine only in the brain", "It blocks DAT instead of causing release", "It is metabolized by CYP3A4 only after chewing"], "It is indicated for ADHD and binge eating disorder, and enzymatic activation reduces misuse.", sP(15));
SG(PS, 2, "Which metabolizing enzyme is listed for mixed amphetamine salts?", "CYP2D6", ["CYP1A2", "CYP2C9", "CYP3A4"], "Adderall has a half-life of about 10 hours. Avoid late dosing because of insomnia, and note the 14-day MAOI washout.", sP(14));
SG(PS, 3, "What is the mechanism of modafinil?", "Weak DAT inhibition with increased histamine and orexin signaling in the hypothalamus", ["Release of dopamine through reversal of VMAT2", "Blockade of NET only", "Agonism of GABA-A receptors"], "Indications include narcolepsy, obstructive sleep apnea related fatigue and shift work sleep disorder.", sP(16));
SG(PS, 2, "What drug interaction counseling applies to modafinil?", "It may lower the effect of hormonal contraceptives, so a backup method is advised", ["It raises the effect of hormonal contraceptives", "It must not be taken with any food", "It causes a hypertensive crisis with tyramine"], "Modafinil induces CYP3A4 and inhibits CYP2C19. It is Schedule IV.", sP(16));
SG(PS, 2, "How does armodafinil relate to modafinil?", "It is the R-enantiomer and is longer acting", ["It is a prodrug of modafinil", "It is the S-enantiomer and has a shorter half-life", "It is an amphetamine derivative"], "Armodafinil is preferred for sustained wakefulness and is also Schedule IV.", sP(17));
SG(PS, 2, "Which use of modafinil or lisdexamfetamine is described as off-label?", "Augmentation in treatment-resistant depression", ["First-line treatment of narcolepsy", "Treatment of Parkinson disease tremor", "Prevention of migraine"], "Modafinil and methylphenidate are also used off-label for fatigue and cognitive disorders.", sP(12));
// Pain and opioids
SG(OP, 1, "In which order do the main steps of the pain pathway occur?", "Nociceptor and peripheral nerve, spinal cord, thalamic relay, cortical processing, then modulation", ["Perception in the cortex, thalamic relay, spinal cord transmission, then the nociceptor", "Spinal cord transmission, the nociceptor, cortical perception, then the thalamus", "Thalamic relay, nociceptor activation, cortical perception, then spinal transmission"], "The periaqueductal gray takes part in descending modulation of pain.", sO(4));
SG(OP, 2, "Which are the three families of endogenous opioid peptides?", "Enkephalins, endorphins and dynorphins", ["Triptans, ergots and gepirones", "Enkephalins, endomorphins and orexins", "Dynorphins, oxytocins and vasopressins"], "Each family comes from a large precursor that is cleaved into several peptides.", sO(6));
SG(OP, 2, "Which major opioid peptide comes from proopiomelanocortin?", "Beta-endorphin", ["Met-enkephalin", "Dynorphin A", "Nociceptin"], "POMC gives the potent opioid agonist beta-endorphin.", sO(12));
SG(OP, 2, "Which precursor contains many copies of met-enkephalin and one of leu-enkephalin?", "Proenkephalin", ["Prodynorphin", "Proopiomelanocortin", "Prepronociceptin"], "Prodynorphin gives dynorphin A, dynorphin B (rimorphin) and neoendorphin, which all begin with the leu-enkephalin sequence.", sO(12));
SG(OP, 3, "Which statement about nociceptin (orphanin FQ) is true?", "It is structurally similar to dynorphin A", ["It is a potent endorphin made from proopiomelanocortin in the pituitary gland", "It is a synthetic mu agonist", "It is a pan opioid antagonist"], "N/OFQ acts on its own receptor and is not blocked well by classic opioid antagonists.", sO(12));
SG(OP, 2, "Which selective agonists are used to study the three opioid receptor subtypes?", "DAMGO for MOR, DPDPE for DOR and U-50,488 for KOR", ["DAMGO for KOR, DPDPE for MOR and U-50,488 for DOR", "Naloxone for MOR, naltrexone for DOR and morphine for KOR", "Fentanyl for MOR, heroin for DOR and codeine for KOR"], "Nearly all clinically useful opioid agonists target the mu receptor.", sO(16));
SG(OP, 1, "Naloxone and naltrexone are best described as:", "Pan antagonists with affinity for all opioid receptors", ["Selective mu agonists", "Kappa partial agonists", "Delta receptor agonists"], "They reverse opioid effects at MOR, DOR and KOR.", sO(17));
SG(OP, 2, "What are the cellular effects of opioid receptor activation?", "Inhibited adenylyl cyclase, reduced presynaptic Ca2+ channel opening and increased K+ current through GIRK channels", ["Increased cAMP and increased presynaptic calcium entry, which raise transmitter release", "Opening of Na+ channels, which depolarizes the neuron and increases firing", "Activation of Gq with release of calcium from stores and activation of PKC only"], "These effects reduce neurotransmitter release and hyperpolarize the postsynaptic neuron.", sO(21));
SG(OP, 3, "After prolonged exposure, what happens to opioid receptors?", "MORs internalize and recycle, DORs are degraded, and KORs do not internalize", ["MORs are degraded, DORs recycle, and KORs internalize", "All three receptors recycle equally", "None of the receptors internalizes"], "Trafficking differences help explain different effects of different opioids.", sO(22));
SG(OP, 3, "Which statement about morphine and MOR internalization is true?", "Morphine decreases adenylyl cyclase activity well but causes little internalization, unlike enkephalins and etorphine", ["Morphine causes the most rapid MOR internalization of any agonist, more than enkephalins", "Morphine does not bind MOR and acts only through delta receptors", "Morphine increases adenylyl cyclase activity while enkephalins decrease it"], "Different ligands cause different receptor conformations and signaling, which is the idea of biased agonism.", sO(24));
SG(OP, 2, "How is desensitization different from tolerance?", "Desensitization is a transient loss of response over minutes to hours, while tolerance develops over days to weeks", ["Desensitization lasts weeks and tolerance lasts minutes, and both fade at the same rate", "Desensitization is a withdrawal syndrome that appears when the drug is stopped", "They mean the same thing, and the only difference is the length of time"], "Tolerance shows as a right shift in the dose response curve or a lower maximum effect and fades over weeks after the drug is removed.", sO(25));
SG(OP, 2, "Which opioid effect shows little or no tolerance with chronic use?", "Pupillary miosis", ["Euphoria", "Analgesia", "Constipation"], "Euphoria develops tolerance rapidly, while analgesia, sedation, emesis and constipation develop moderate tolerance.", sO(26));
SG(OP, 2, "Why do chronic heroin users still have pinpoint pupils while needing higher doses?", "Miosis shows little tolerance while euphoria shows rapid tolerance", ["Heroin stops working on the pupil only", "Pinpoint pupils come from withdrawal", "Euphoria shows no tolerance"], "Miosis can be a sign of overdose even in a highly tolerant patient.", sO(26));
SG(OP, 2, "What is the basis of opioid rotation?", "Cross-tolerance between opioids is incomplete", ["Cross-tolerance is complete between all opioids", "Different opioids use different receptor classes entirely", "Opioids never cause tolerance"], "A patient tolerant to one mu agonist may respond to a different agonist at a lower equianalgesic dose.", sO(27));
SG(OP, 2, "Which best defines physical dependence?", "A state of adaptation shown by a withdrawal syndrome when the drug is stopped or an antagonist is given", ["Compulsive drug seeking that continues despite physical or social harm", "A right shift in the dose response curve after repeated administration", "An acute loss of receptor response that lasts only minutes to hours"], "Opioid withdrawal includes agitation, hyperalgesia, diarrhea, pupillary dilation and dysphoria.", sO(28));
SG(OP, 2, "Which best defines addiction?", "Compulsive drug use and seeking despite physical, emotional or social harm", ["A withdrawal syndrome that appears when the drug is stopped or an antagonist is given", "A reduced response to the drug over days to weeks that fades after stopping", "A transient loss of receptor signaling that recovers within hours"], "Dependence is not synonymous with addiction. Rewarding effects drive initiation, and avoiding withdrawal can drive continued use.", sO(29));
SG(OP, 3, "How does chronic opioid exposure contribute to analgesic tolerance at the system level?", "PKC activation enhances NMDA glutamate receptor activity and dorsal horn excitability", ["It permanently destroys mu receptors", "It blocks enkephalin synthesis in the liver", "It increases GABA-A receptor expression in the thalamus"], "NMDA receptors act as an excitatory link in enhanced pain processing, which also explains why NMDA antagonists can help.", sO(32));
SG(OP, 2, "Which statement about opioid effectiveness across pain types is correct?", "Opioids work best for acute nociceptive pain, and neuropathic pain responds less well", ["Opioids are first line for chronic neuropathic pain", "Opioids work best for mild pain, with no effect on severe pain", "Opioids do not work at all in nociceptive pain"], "Long-term use for chronic pain is no longer first line. NSAIDs, anticonvulsants and antidepressants are often tried first.", sO(3));
SG(OP, 2, "Where do opioids act to relieve pain?", "At peripheral nerve endings, the spinal dorsal horn and brain regions such as the PAG and thalamus", ["Only on skeletal muscle cells, where opioid receptors cause relaxation", "Only in the dorsal root ganglia, with no effect in the spinal cord or brain", "Only in the cerebellum, which processes the sensation of pain"], "Opioid receptors are widely distributed on neuron cell bodies and terminals in the periphery and the neuraxis.", sO(15));
SG(OP, 2, "Which effects other than pain relief are produced by mu opioid agonists?", "Respiratory depression, constipation, miosis, nausea and vomiting, sedation and cough suppression", ["Hypertension, diarrhea, mydriasis and agitation, which mirror withdrawal", "Tachycardia, bronchodilation and increased alertness with raised heart rate", "Hyperalgesia and insomnia, with no change in the pupils or bowel"], "Constipation and miosis are not lost easily with continued use, while euphoria quickly develops tolerance.", sD);
SG(OP, 2, "Which prodrug is converted to morphine by CYP2D6 and also suppresses cough?", "Codeine", ["Fentanyl", "Oxycodone", "Loperamide"], "Poor 2D6 metabolizers get little pain relief, and ultra-rapid metabolizers risk toxicity.", sD);
SG(OP, 2, "Why is heroin more euphoric than morphine?", "Its lipophilic structure crosses the blood-brain barrier quickly and it is converted to 6-monoacetylmorphine and morphine", ["It is a kappa agonist that acts mainly in the spinal cord and does not cross the blood-brain barrier", "It is a mu antagonist that is converted into an agonist only in the liver", "It is not metabolized, so it acts slowly and stays in the blood for days"], "Heroin is diacetylmorphine.", sD);
SG(OP, 2, "Which opioid risks serotonin syndrome with MAOIs and has a metabolite that causes seizures?", "Meperidine", ["Morphine", "Hydromorphone", "Oxymorphone"], "The metabolite is normeperidine. Tramadol also interacts with MAOIs.", sD);
SG(OP, 2, "Which opioid acts as a weak mu agonist plus a serotonin and norepinephrine reuptake inhibitor, and can cause seizures?", "Tramadol", ["Methadone", "Levorphanol", "Fentanyl"], "Combining it with serotonergic drugs raises the risk of serotonin syndrome.", sD);
SG(OP, 2, "Loperamide helps diarrhea at normal doses without central effects because:", "It is a P-glycoprotein substrate that is kept out of the brain", ["It is a delta agonist that is not absorbed from the gut, so it stays local", "It does not bind opioid receptors and works by blocking gut calcium channels", "It is not absorbed by gut mucosa, so it acts only in the stomach"], "It acts on mu receptors in the gut to slow motility. Very high doses can overcome this and cause cardiac toxicity.", sD);
SG(OP, 2, "Which opioid is a long-acting drug with NMDA antagonist activity and QT prolongation risk?", "Methadone", ["Hydrocodone", "Codeine", "Diphenoxylate"], "It is used for pain and for opioid use disorder.", sD);
SG(OP, 2, "Fentanyl is characterized by:", "Very high potency and high lipophilicity, and it is available as a transdermal patch", ["Low potency and poor lipid solubility, with an oral dose used only for chronic pain control", "Antagonist activity at mu receptors, which is used to reverse overdose", "Use only as an antidiarrheal, with no central or analgesic effects"], "Its potency makes accidental overdose a major risk.", sD);
SG(OP, 2, "Which semisynthetic opioids are mu agonists used for moderate to severe pain, like oxycodone, hydrocodone, hydromorphone and oxymorphone?", "Full mu receptor agonists", ["Mu receptor antagonists", "Kappa-only agonists", "Delta antagonists"], "Their differences are mostly potency, formulation and duration.", sD);
SG(OP, 2, "Why can naloxone need repeated doses after an overdose of a long-acting opioid?", "Naloxone has a shorter duration of action than many opioids", ["Naloxone is metabolized into an agonist", "Naloxone only works the first time", "Opioids cause naloxone resistance by receptor loss after the first dose is given"], "Naloxone is a competitive antagonist and can precipitate withdrawal in dependent patients.", sD);
SG(OP, 3, "Which synaptic mechanism makes opioids rewarding and addictive?", "Opioids inhibit GABA interneurons that restrain dopamine neurons, so dopamine release in the reward pathway rises", ["Opioids block dopamine reuptake in the nucleus accumbens, which raises dopamine directly", "Opioids activate GABA interneurons in the VTA, which lowers dopamine release", "Opioids block NMDA receptors in the spinal cord, which causes reward"], "Mu receptor activation on VTA GABA neurons disinhibits dopamine neurons.", sO(29));
